<script setup lang="ts">import{ref}from'vue';import type{RecentPayment}from '@/types/dashboard';defineProps<{items:RecentPayment[];loading:boolean}>();const emit=defineEmits<{print:[id:number];detail:[id:number]}>();const search=ref('');const money=(v:number)=>new Intl.NumberFormat('vi-VN',{style:'currency',currency:'VND',maximumFractionDigits:0}).format(v);const statuses:Record<string,[string,string]>={CHO_PHAT_HANH:['Chờ phát hành','warning'],DA_PHAT_HANH:['Đã phát hành','success'],PHAT_HANH_LOI:['Lỗi','error']};const status=(v:string)=>statuses[v]||['Chưa có','default']</script>
<template><v-card border rounded="xl"><div class="d-flex flex-column flex-sm-row justify-space-between align-sm-center ga-3 pa-4 pa-md-5"><div><div class="text-h6 font-weight-bold">Giao dịch gần nhất</div><div class="text-caption text-medium-emphasis">Các phiếu thu mới nhất theo bộ lọc</div></div><v-text-field v-model="search" density="compact" prepend-inner-icon="mdi-magnify" label="Tìm giao dịch" hide-details clearable max-width="280"/></div><v-divider/><v-data-table :headers="[{title:'Thời gian',key:'paid_at'},{title:'Mã phiếu',key:'code'},{title:'Chủ hộ',key:'household_name'},{title:'Tuyến',key:'route_name'},{title:'Nhân viên',key:'collector_name'},{title:'Kỳ thu',key:'period'},{title:'Dịch vụ',key:'service_name'},{title:'Số tiền',key:'amount',align:'end'},{title:'Hóa đơn',key:'invoice_status'},{title:'',key:'actions',sortable:false}]" :items="items" :search="search" :loading="loading" hover items-per-page="8"><template #item.paid_at="{value}"><span class="text-no-wrap">{{ new Date(value).toLocaleString('vi-VN') }}</span></template><template #item.amount="{value}"><strong class="text-primary text-no-wrap">{{ money(value) }}</strong></template><template #item.invoice_status="{value}"><v-chip :color="status(value)[1]" size="small" variant="tonal">{{ status(value)[0] }}</v-chip></template><template #item.actions="{item}"><v-menu><template #activator="{props}"><v-btn v-bind="props" icon="mdi-dots-vertical" size="small" variant="text"/></template><v-list density="compact"><v-list-item title="Xem chi tiết" prepend-icon="mdi-eye-outline" @click="emit('detail',(item as any).id)"/><v-list-item title="In lại phiếu thu" prepend-icon="mdi-printer-outline" @click="emit('print',(item as any).id)"/></v-list></v-menu></template><template #no-data><div class="empty-state">Chưa có giao dịch</div></template></v-data-table></v-card></template>
